/**
 * Writes server/db/migrations.generated.ts, which embeds the SQL migration files so bundled
 * serverless functions can migrate without reading files from disk. Run after changing any
 * migration (npm run db:embed); tests/unit/migrations-embed.test.ts fails if it is stale.
 */
import { writeFile } from 'node:fs/promises';
import { readMigrationFiles } from '../server/db/migrate';

export async function renderEmbedded(): Promise<string> {
  const files = await readMigrationFiles('server/db/migrations');
  return [
    '// GENERATED by scripts/embed-migrations.ts — do not edit. Source: server/db/migrations/*.sql',
    "import type { MigrationFile } from './migrate';",
    '',
    `export const EMBEDDED_MIGRATIONS: MigrationFile[] = ${JSON.stringify(files, null, 2)};`,
    '',
  ].join('\n');
}

if (process.argv[1]?.endsWith('embed-migrations.ts')) {
  await writeFile('server/db/migrations.generated.ts', await renderEmbedded());
  console.log('wrote server/db/migrations.generated.ts');
}
